Myers O(ND):
```
func diff(a, b []string) []Op {
    n, m := len(a), len(b)
    max := n + m
    if max == 0 { return nil }
    v := make([]int, 2*max+1)
    offset := max
    trace := make([][]int, 0, max+1)
    var d int
    found := false
    for d = 0; d <= max; d++ {
        // copy v for trace
        vc := make([]int, len(v))
        copy(vc, v)
        trace = append(trace, vc)
        for k := -d; k <= d; k += 2 {
            var x int
            if k == -d || (k != d && v[offset+k-1] < v[offset+k+1]) {
                x = v[offset+k+1] // down (insert from b)
            } else {
                x = v[offset+k-1] + 1 // right (delete from a)
            }
            y := x - k
            for x < n && y < m && a[x] == b[y] {
                x++
                y++
            }
            v[offset+k] = x
            if x >= n && y >= m {
                found = true
                break
            }
        }
        if found { break }
    }
    // backtrack
    ops := []Op{}
    x, y := n, m
    for d := len(trace)-1; d > 0; d-- {
        v := trace[d]
        k := x - y
        var prevK int
        if k == -d || (k != d && v[offset+k-1] < v[offset+k+1]) {
            prevK = k + 1
        } else {
            prevK = k - 1
        }
        prevX := v[offset+prevK]
        prevY := prevX - prevK
        for x > prevX && y > prevY {
            ops = append(ops, Op{OpEqual, a[x-1]})
            x--
            y--
        }
        if d > 0 {
            if x == prevX {
                ops = append(ops, Op{OpInsert, b[y-1]})
                y--
            } else {
                ops = append(ops, Op{OpDelete, a[x-1]})
                x--
            }
        }
    }
    // remaining leading equals
    for x > 0 && y > 0 {
        ops = append(ops, Op{OpEqual, a[x-1]})
        x--
        y--
    }
    // reverse
    for i, j := 0, len(ops)-1; i < j; i, j = i+1, j-1 {
        ops[i], ops[j] = ops[j], ops[i]
    }
    return ops
}
```

